/* locked serial-port Zephyr binding: only authored capabilities receive
 * uart_driver_api slots; event delivery and endpoint identity remain L2. */
static int c5_pl011_uart_poll_in(const struct device *dev, unsigned char *c)
{
	struct c5_pl011_data *data = dev->data;
	struct SerialRxBuffer buffer = { .data = c, .len = 1, .errors = &data->__rseq_line_errors };

	return c5_pl011_serial_receive(&data->inner, buffer) == 1 ? 0 : -1;
}

#ifdef CONFIG_UART_INTERRUPT_DRIVEN
static int c5_pl011_uart_fifo_read(const struct device *dev, uint8_t *buf, const int size)
{
	struct c5_pl011_data *data = dev->data;
	struct SerialRxBuffer buffer = { .data = buf, .len = size > 0 ? (size_t)size : 0, .errors = &data->__rseq_line_errors };

	return (int)c5_pl011_serial_receive(&data->inner, buffer);
}
#endif

static void c5_pl011_uart_poll_out(const struct device *dev, unsigned char c)
{
	struct c5_pl011_data *data = dev->data;
	struct SerialTxBuffer buffer = { .data = &c, .len = 1 };

	(void)c5_pl011_serial_transmit(&data->inner, buffer);
}

#ifdef CONFIG_UART_INTERRUPT_DRIVEN
static int c5_pl011_uart_fifo_fill(const struct device *dev, const uint8_t *buf, int size)
{
	struct c5_pl011_data *data = dev->data;
	struct SerialTxBuffer buffer = { .data = (uint8_t *)buf, .len = size > 0 ? (size_t)size : 0 };

	return (int)c5_pl011_serial_transmit(&data->inner, buffer);
}
#endif

static int c5_pl011_uart_err_check(const struct device *dev)
{
	struct c5_pl011_data *data = dev->data;
	struct LineErrorFlags errors = data->__rseq_line_errors;
	int result = 0;

	data->__rseq_line_errors = (struct LineErrorFlags){0};
	if (errors.break_detected) result |= UART_BREAK;
	if (errors.framing) result |= UART_ERROR_FRAMING;
	if (errors.parity) result |= UART_ERROR_PARITY;
	if (errors.overrun) result |= UART_ERROR_OVERRUN;
	return result;
}

